// Compare engine G-code with desktop OrcaSlicer reference G-code.
//
// Normalization (the only difference allowed):
//   "; generated by OrcaSlicer <ver> on <date> at <time>"  — the date and time only; the
//   program name and version must match.
// Everything else must be byte-identical. When it is not, differences are classified so a
// toolchain artefact (e.g. last-digit float formatting) can be told apart from real behaviour
// changes.
//
// SPDX-License-Identifier: AGPL-3.0-or-later

const TIMESTAMP = /^(; generated by .*) on \d{4}-\d{2}-\d{2} at \d{2}:\d{2}:\d{2}( UTC)?$/;

export function normalize(text) {
  return text.split(/\r?\n/).map((l) => l.replace(TIMESTAMP, '$1 on <date>'));
}

// Numbers as G-code writes them, including a bare leading point ("E-.05306").
const NUM = /-?(?:\d+(?:\.\d*)?|\.\d+)(?:e[-+]?\d+)?/gi;

function numericOnly(a, b) {
  if (a.replace(NUM, '#') !== b.replace(NUM, '#')) return null;
  const na = a.match(NUM) ?? [];
  const nb = b.match(NUM) ?? [];
  let max = 0;
  for (let i = 0; i < na.length; i++) max = Math.max(max, Math.abs(Number(na[i]) - Number(nb[i])));
  return max;
}

/** Returns {identical, lines:{ref,got}, firstDiff, numericOnly, maxNumericDelta, structural, samples[]} */
export function compareGcode(refText, gotText, { maxSamples = 20 } = {}) {
  const ref = normalize(refText);
  const got = normalize(gotText);
  const out = { identical: false, lines: { ref: ref.length, got: got.length }, firstDiff: -1,
    numericOnly: 0, maxNumericDelta: 0, structural: 0, samples: [] };
  const n = Math.max(ref.length, got.length);
  for (let i = 0; i < n; i++) {
    const a = ref[i], b = got[i];
    if (a === b) continue;
    if (out.firstDiff < 0) out.firstDiff = i + 1;
    const d = a !== undefined && b !== undefined ? numericOnly(a, b) : null;
    if (d !== null) { out.numericOnly++; out.maxNumericDelta = Math.max(out.maxNumericDelta, d); }
    else out.structural++;
    if (out.samples.length < maxSamples) out.samples.push({ line: i + 1, ref: a ?? '<eof>', got: b ?? '<eof>' });
    // After a structural difference (insert/delete) everything shifts; stop counting noise.
    if (out.structural > 200) break;
  }
  out.identical = out.firstDiff < 0;
  return out;
}

// CLI: node gcode-compare.mjs ref.gcode[.gz] got.gcode
if (import.meta.url === `file://${process.argv[1]}`) {
  const { readFileSync } = await import('node:fs');
  const { gunzipSync } = await import('node:zlib');
  const read = (p) => (p.endsWith('.gz') ? gunzipSync(readFileSync(p)) : readFileSync(p)).toString('utf8');
  const r = compareGcode(read(process.argv[2]), read(process.argv[3]));
  console.log(JSON.stringify(r, null, 2));
  process.exit(r.identical ? 0 : 1);
}
